bool file_text_files_write_int(const char* path, const int* data, size_t count) {
    if (!path || !data || count == 0) return false;
    FILE* fp = fopen(path, "wb");
    if (!fp) return false;
    size_t written = fwrite(data, sizeof(int), count, fp);
    fclose(fp);
    return written == count;
}

size_t file_text_files_read_int(const char* path, int* buffer, size_t max_count) {
    if (!path || !buffer || max_count == 0) return 0;
    FILE* fp = fopen(path, "rb");
    if (!fp) return 0;
    size_t read_count = fread(buffer, sizeof(int), max_count, fp);
    fclose(fp);
    return read_count;
}

